/* One focus session per open app. Persist deadlines, never infer elapsed time from interval ticks. */
(()=>{
  let session=null,tick=null,saving=false;
  const dialog=document.createElement('dialog');dialog.id='focus-timer';dialog.innerHTML='<div class="dialog-head"><h2 id="focus-title">Time for your habit</h2><button class="icon-button" data-close="focus-timer" aria-label="Close">×</button></div><p id="focus-name"></p><div id="focus-clock" style="font-size:56px;font-weight:800;text-align:center;font-variant-numeric:tabular-nums;margin:24px 0">00:00</div><p id="focus-status" role="status"></p><div class="dialog-actions"><button class="secondary" id="focus-cancel">Finish without saving</button><button class="primary" id="focus-toggle">Pause</button></div><p class="muted">Progress is saved when the timer finishes. You can close this dialog; reloading the app ends the session.</p>';document.body.append(dialog);
  function controls(){document.querySelectorAll('.habit[data-habit]').forEach(row=>{const h=state.habits.find(h=>h.id===row.dataset.habit);if(!h||view!=='today'||selected!==R.today()||R.configAt(h,selected).type!=='minutes'||row.querySelector('[data-focus]'))return;const b=document.createElement('button');b.className='text-button';b.dataset.focus=h.id;b.textContent=session?.id===h.id?'Timer':'▶ Timer';row.querySelector('.habit-actions').prepend(b)})}
  const observer=new MutationObserver(controls);observer.observe(document.querySelector('#content'),{childList:true,subtree:true});controls();
  async function update(){if(!session)return;const remaining=session.paused?session.remaining:Math.max(0,session.deadline-Date.now());const sec=Math.ceil(remaining/1000);dialog.querySelector('#focus-clock').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');if(remaining>0||session.paused||saving)return;
    saving=true;const current=session;dialog.querySelector('#focus-status').textContent='Saving your result…';
    const ok=await transact(s=>{const h=s.habits.find(h=>h.id===current.id);if(!h||!R.scheduled(s,h,current.date))throw Error('Habit is no longer available.');s.logs[current.date]??={};s.logs[current.date][h.id]=Math.max(R.value(s,h,current.date),current.target)});
    saving=false;if(ok){clearInterval(tick);session=null;dialog.querySelector('#focus-status').textContent='Done! Your time has been added to your progress.';dialog.querySelector('#focus-toggle').textContent='Close';dialog.querySelector('#focus-cancel').hidden=true;notify('Session complete. Progress saved.')}else{session.paused=true;session.remaining=0;dialog.querySelector('#focus-status').textContent='Could not save. Select Retry saving.';dialog.querySelector('#focus-toggle').textContent='Retry saving'}
  }
  document.addEventListener('click',e=>{const b=e.target.closest('[data-focus]');if(!b)return;if(blocked)return notify('First load your progress.');if(session&&session.id!==b.dataset.focus)return notify('Finish your current timer first.');if(!session){const h=state.habits.find(h=>h.id===b.dataset.focus),c=R.configAt(h,selected),minutes=Math.max(0,c.target-R.value(state,h,selected));if(!minutes)return notify('Today’s goal is already complete.');session={id:h.id,date:selected,target:c.target,remaining:minutes*60000,deadline:Date.now()+minutes*60000,paused:false};dialog.querySelector('#focus-name').textContent=h.name;dialog.querySelector('#focus-status').textContent='Time to focus on your habit.';dialog.querySelector('#focus-toggle').textContent='Pause';dialog.querySelector('#focus-cancel').hidden=false;tick=setInterval(update,500)}dialog.showModal();update()});
  dialog.querySelector('#focus-toggle').onclick=()=>{if(!session)return dialog.close();if(saving)return;if(session.paused){session.deadline=Date.now()+session.remaining;session.paused=false;dialog.querySelector('#focus-toggle').textContent='Pause'}else{session.remaining=Math.max(0,session.deadline-Date.now());session.paused=true;dialog.querySelector('#focus-toggle').textContent='Resume'}update()};
  dialog.querySelector('#focus-cancel').onclick=()=>{if(saving)return;clearInterval(tick);session=null;dialog.close();notify('Timer stopped without saving progress')};
  window.addEventListener('beforeunload',e=>{if(session){e.preventDefault();e.returnValue=''}});
})();
